<?php
require __DIR__.'/_common.php';
if(isset($_GET['logout'])){$_SESSION=[];session_destroy();header('Location: ./');exit;}
if(empty($_SESSION['somba_admin'])){ $error=null; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$s=db()->prepare("SELECT id,email,password_hash,role,status FROM users WHERE email=? LIMIT 1");$s->execute([$email]);$u=$s->fetch();if($u&&$u['role']==='admin'&&$u['status']==='active'&&password_verify($password,(string)$u['password_hash'])){$_SESSION['somba_admin']=['id'=>(int)$u['id'],'email'=>$u['email']];$pdo=db();$pdo->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([(int)$u['id']]);header('Location: ./');exit;}$error='Identifiants invalides.';}?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SOMBA Admin</title><link rel="stylesheet" href="assets/admin.css"></head><body><main class="login"><h1>SOMBA</h1><p>Administration</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><form method="post"><input name="email" type="email" placeholder="Email administrateur" required><input name="password" type="password" placeholder="Mot de passe" required><button>Connexion</button></form></main></body></html><?php exit;}
try{$pdo=db();$stats=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'active'=>(int)$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'paid'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE payment_status='paid'")->fetchColumn(),'delivered'=>(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE delivery_status='delivered'")->fetchColumn(),'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM orders WHERE payment_status='paid'")->fetchColumn(),'users'=>(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()];$orders=$pdo->query("SELECT o.*,p.name product,g.name game FROM orders o JOIN products p ON p.id=o.product_id JOIN games g ON g.id=p.game_id ORDER BY o.created_at DESC LIMIT 20")->fetchAll();}catch(Throwable $e){http_response_code(500);exit('Database unavailable');}admin_layout_start('Dashboard');echo '<div class="stats"><div><b>'.h($stats['products']).'</b><span>Produits</span></div><div><b>'.h($stats['active']).'</b><span>Produits actifs</span></div><div><b>'.h($stats['users']).'</b><span>Utilisateurs</span></div><div><b>'.h($stats['orders']).'</b><span>Commandes</span></div><div><b>'.h($stats['paid']).'</b><span>Payées</span></div><div><b>'.h($stats['delivered']).'</b><span>Livrées</span></div><div><b>'.h(number_format($stats['revenue'],0,',',' ')).' XAF</b><span>Chiffre d’affaires</span></div></div><h2>Dernières commandes</h2><table><tr><th>N°</th><th>Client</th><th>Produit</th><th>Montant</th><th>Paiement</th><th>Livraison</th></tr>';foreach($orders as $o)echo '<tr><td>'.h($o['order_number']).'</td><td>'.h($o['customer_email']??'').'</td><td>'.h($o['game'].' / '.$o['product']).'</td><td>'.h($o['amount'].' '.$o['currency']).'</td><td>'.h($o['payment_status']).'</td><td>'.h($o['delivery_status']).'</td></tr>';echo '</table>';admin_layout_end();